enum AttendanceStatus {
  present('Present', 'P'), absent('Absent', 'A'), leave('On leave', 'L'),
  off('Weekly off', 'O'), upcoming('No record', '-');
  const AttendanceStatus(this.label, this.code);
  final String label;
  final String code;
}

class DayRecord {
  const DayRecord(this.date, this.status, {this.checkIn, this.checkOut,
    this.breakMinutes = 0, this.snapshotAt});
  final DateTime date;
  final AttendanceStatus status;
  final DateTime? checkIn, checkOut, snapshotAt;
  final int breakMinutes;
  Duration get workingTime {
    if (checkIn == null || (checkOut ?? snapshotAt) == null) return Duration.zero;
    final minutes = (checkOut ?? snapshotAt)!.difference(checkIn!).inMinutes - breakMinutes;
    return Duration(minutes: minutes < 0 ? 0 : minutes);
  }
  String get hoursLabel => '${workingTime.inHours}h ${workingTime.inMinutes.remainder(60).toString().padLeft(2, '0')}m';
}

class DemoRequest {
  const DemoRequest({required this.title, required this.detail});
  final String title, detail;
}

