import 'package:flutter/foundation.dart';
import '../models/workday.dart';

/// Deterministic sample data, isolated from widgets for a future API service.
/// Requests live only in the authenticated shell and disappear on logout.
class WorkdayController extends ChangeNotifier {
  WorkdayController({DateTime? today}) : today = DateUtilsLocal.dateOnly(today ?? DateTime.now());
  final DateTime today;
  final List<DemoRequest> _leaves = [];
  final List<DemoRequest> _materials = [];
  List<DemoRequest> get leaves => List.unmodifiable(_leaves);
  List<DemoRequest> get materials => List.unmodifiable(_materials);

  DayRecord record(DateTime date) {
    final day = DateUtilsLocal.dateOnly(date);
    if (day.isAfter(today)) return DayRecord(day, AttendanceStatus.upcoming);
    if (day == today) {
      return DayRecord(day, AttendanceStatus.present,
        checkIn: DateTime(day.year, day.month, day.day, 9, 2),
        snapshotAt: DateTime(day.year, day.month, day.day, 14),
        breakMinutes: 30);
    }
    if (day.weekday == DateTime.sunday) return DayRecord(day, AttendanceStatus.off);
    if (day.day % 11 == 0) return DayRecord(day, AttendanceStatus.leave);
    if (day.day % 7 == 0) return DayRecord(day, AttendanceStatus.absent);
    return DayRecord(day, AttendanceStatus.present,
      checkIn: DateTime(day.year, day.month, day.day, 9),
      checkOut: DateTime(day.year, day.month, day.day, 18), breakMinutes: 60);
  }

  void addLeave(DemoRequest request) { _leaves.insert(0, request); notifyListeners(); }
  void addMaterial(DemoRequest request) { _materials.insert(0, request); notifyListeners(); }
}

abstract final class DateUtilsLocal {
  static DateTime dateOnly(DateTime date) => DateTime(date.year, date.month, date.day);
}

