import 'package:flutter/material.dart';
import '../models/workday.dart';
import '../services/workday_controller.dart';
import '../theme/brand_theme.dart';
import '../widgets/common.dart';
import '../widgets/workday_widgets.dart';

class AttendanceScreen extends StatefulWidget {
  const AttendanceScreen({super.key, required this.workday, required this.onLeave});
  final WorkdayController workday;
  final VoidCallback onLeave;
  @override
  State<AttendanceScreen> createState() => _AttendanceScreenState();
}
class _AttendanceScreenState extends State<AttendanceScreen> {
  late DateTime _month;
  late DateTime _selected;
  @override
  void initState() {
    super.initState(); _selected = widget.workday.today;
    _month = DateTime(_selected.year, _selected.month);
  }
  Color _color(AttendanceStatus status) => switch (status) {
    AttendanceStatus.present => Brand.forest,
    AttendanceStatus.absent => const Color(0xFFAD302A),
    AttendanceStatus.leave => const Color(0xFF805B09),
    AttendanceStatus.off => const Color(0xFF526476),
    AttendanceStatus.upcoming => const Color(0xFF626B60),
  };
  void _move(int delta) => setState(() {
    _month = DateTime(_month.year, _month.month + delta);
    _selected = _month;
  });
  @override
  Widget build(BuildContext context) {
    final local = MaterialLocalizations.of(context);
    final days = DateTime(_month.year, _month.month + 1, 0).day;
    final offset = (_month.weekday - local.firstDayOfWeekIndex) % 7;
    final selected = widget.workday.record(_selected);
    final counts = <AttendanceStatus, int>{};
    for (var day = 1; day <= days; day++) {
      final status = widget.workday.record(DateTime(_month.year, _month.month, day)).status;
      counts[status] = (counts[status] ?? 0) + 1;
    }
    return PageBody(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      const SectionHeading('Attendance', subtitle: 'Your calendar, leave and daily hours'),
      const DemoNotice(),
      const SizedBox(height: 20),
      Row(children: [
        IconButton(tooltip: 'Previous month', onPressed: () => _move(-1),
          icon: const Icon(Icons.chevron_left)),
        Expanded(child: Text(local.formatMonthYear(_month), textAlign: TextAlign.center,
          style: Theme.of(context).textTheme.titleMedium)),
        IconButton(tooltip: 'Next month', onPressed: () => _move(1),
          icon: const Icon(Icons.chevron_right)),
      ]),
      Align(alignment: Alignment.centerRight, child: TextButton(
        onPressed: () => setState(() { _selected = widget.workday.today;
          _month = DateTime(_selected.year, _selected.month); }),
        child: const Text('This month'))),
      Row(children: [
        for (var i = 0; i < 7; i++) Expanded(child: Center(child: Text(
          local.narrowWeekdays[(local.firstDayOfWeekIndex + i) % 7],
          style: const TextStyle(fontWeight: FontWeight.w700)))),
      ]),
      const SizedBox(height: 8),
      LayoutBuilder(builder: (context, constraints) => GridView.builder(
        shrinkWrap: true, physics: const NeverScrollableScrollPhysics(),
        itemCount: ((days + offset + 6) ~/ 7) * 7,
        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: 7, mainAxisSpacing: 6, crossAxisSpacing: 2,
          mainAxisExtent: 56 * MediaQuery.textScalerOf(context).scale(1)),
        itemBuilder: (context, index) {
          final number = index - offset + 1;
          if (number < 1 || number > days) return const SizedBox.shrink();
          final date = DateTime(_month.year, _month.month, number);
          final record = widget.workday.record(date);
          final active = date == _selected;
          return Semantics(
            label: '${local.formatFullDate(date)}, ${record.status.label}',
            selected: active, button: true,
            child: Tooltip(message: record.status.label, child: Material(
              color: active ? Brand.forest : _color(record.status).withValues(alpha: .08),
              borderRadius: BorderRadius.circular(10),
              child: InkWell(key: ValueKey('day-${date.toIso8601String()}'),
                borderRadius: BorderRadius.circular(10),
                onTap: () => setState(() => _selected = date),
                child: ExcludeSemantics(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                  Text('$number', style: TextStyle(fontSize: 12,
                    fontWeight: FontWeight.w700, color: active ? Colors.white : Colors.black87)),
                  const SizedBox(height: 3),
                  Text(record.status.code, style: TextStyle(fontSize: 10,
                    color: active ? Colors.white : _color(record.status))),
                ]))))),
          );
        })),
      const SizedBox(height: 16),
      Wrap(spacing: 12, runSpacing: 10, children: [
        for (final status in AttendanceStatus.values)
          Text('${status.code}  ${status.label}', style: TextStyle(color: _color(status))),
      ]),
      const SectionHeading('Month overview'),
      Wrap(spacing: 8, runSpacing: 8, children: [
        for (final status in AttendanceStatus.values.where((s) => s != AttendanceStatus.upcoming))
          Chip(label: Text('${status.label}: ${counts[status] ?? 0}')),
      ]),
      SectionHeading(local.formatFullDate(_selected)),
      SurfaceCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(selected.status.label, style: TextStyle(color: _color(selected.status),
          fontWeight: FontWeight.w700, fontSize: 20)),
        const SizedBox(height: 16),
        if (selected.status == AttendanceStatus.present) ...[
          Text('Check-in: ${clockLabel(context, selected.checkIn)}'),
          const SizedBox(height: 10),
          Text('Check-out: ${selected.checkOut == null ? "Not yet (demo snapshot)" : clockLabel(context, selected.checkOut)}'),
          const SizedBox(height: 10),
          Text('Break: ${selected.breakMinutes} min'),
          const SizedBox(height: 10), Text('Working hours: ${selected.hoursLabel}'),
        ] else Text(selected.status == AttendanceStatus.upcoming
            ? 'No attendance is recorded for this future date.'
            : 'Sample status. There are no working hours for this date.'),
      ])),
      const SectionHeading('Leave & attendance help'),
      PrimaryButton(label: 'Request leave', icon: Icons.event_available,
        onPressed: widget.onLeave),
      const SizedBox(height: 12),
      const SurfaceCard(child: Text('Missing a punch? Attendance correction and check-in/out will be available after API integration.')),
    ]));
  }
}

