import 'package:flutter/material.dart';
import '../models/workday.dart';
import '../services/workday_controller.dart';
import '../widgets/common.dart';
import '../widgets/workday_widgets.dart';

class RequestScreen extends StatefulWidget {
  const RequestScreen({super.key, required this.workday, required this.leave});
  final WorkdayController workday;
  final bool leave;
  @override
  State<RequestScreen> createState() => _RequestScreenState();
}
class _RequestScreenState extends State<RequestScreen> {
  final _form = GlobalKey<FormState>();
  final _item = TextEditingController();
  final _quantity = TextEditingController();
  final _reason = TextEditingController();
  String _type = 'Casual leave';
  DateTimeRange? _range;
  bool _dateError = false;
  @override
  void dispose() { _item.dispose(); _quantity.dispose(); _reason.dispose(); super.dispose(); }
  String? _required(String? value) => value == null || value.trim().isEmpty ? 'This field is required.' : null;
  Future<void> _dates() async {
    final picked = await showDateRangePicker(context: context,
      firstDate: widget.workday.today,
      lastDate: DateTime(widget.workday.today.year + 1, 12, 31),
      initialDateRange: _range);
    if (picked != null && mounted) setState(() { _range = picked; _dateError = false; });
  }
  void _submit() {
    final valid = _form.currentState!.validate();
    setState(() => _dateError = widget.leave && _range == null);
    if (!valid || _dateError) return;
    FocusScope.of(context).unfocus();
    final local = MaterialLocalizations.of(context);
    final request = DemoRequest(
      title: widget.leave ? _type : _item.text.trim(),
      detail: widget.leave
        ? '${local.formatMediumDate(_range!.start)} - ${local.formatMediumDate(_range!.end)}\n${_reason.text.trim()}'
        : 'Quantity: ${_quantity.text.trim()}\n${_reason.text.trim()}');
    if (widget.leave) { widget.workday.addLeave(request); }
    else { widget.workday.addMaterial(request); }
    setState(() { _item.clear(); _quantity.clear(); _reason.clear(); _range = null; });
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Demo request added on this device only. Nothing was sent.')));
  }
  @override
  Widget build(BuildContext context) {
    final local = MaterialLocalizations.of(context);
    final requests = widget.leave ? widget.workday.leaves : widget.workday.materials;
    return PageBody(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      SectionHeading(widget.leave ? 'Leave Request' : 'Material Request',
        subtitle: widget.leave ? 'Plan your time away' : 'Request supplies for your store'),
      const DemoNotice(text: 'UI preview only. Requests are kept in this session and cleared on logout. No approval or stock movement occurs.'),
      const SizedBox(height: 20),
      Form(key: _form, child: Column(children: [
        if (widget.leave) ...[
          DropdownButtonFormField<String>(initialValue: _type, isExpanded: true,
            decoration: const InputDecoration(labelText: 'Leave type'),
            items: ['Casual leave', 'Sick leave', 'Earned leave'].map((type) =>
              DropdownMenuItem(value: type, child: Text(type))).toList(),
            onChanged: (value) => setState(() => _type = value!)),
          const SizedBox(height: 16),
          OutlinedButton.icon(key: const ValueKey('leave-dates'), onPressed: _dates,
            icon: const Icon(Icons.date_range),
            label: Padding(padding: const EdgeInsets.symmetric(vertical: 16),
              child: Text(_range == null ? 'Select leave dates'
                : '${local.formatMediumDate(_range!.start)} - ${local.formatMediumDate(_range!.end)}'))),
          if (_dateError) const Text('Select your leave dates.', style: TextStyle(color: Colors.red)),
        ] else ...[
          TextFormField(controller: _item, validator: _required,
            decoration: const InputDecoration(labelText: 'Material / item name')),
          const SizedBox(height: 16),
          TextFormField(controller: _quantity, keyboardType: TextInputType.number,
            validator: (value) {
              final quantity = int.tryParse(value?.trim() ?? '');
              return quantity == null || quantity <= 0 ? 'Enter a whole number greater than zero.' : null;
            }, decoration: const InputDecoration(labelText: 'Quantity (units)')),
        ],
        const SizedBox(height: 16),
        TextFormField(controller: _reason, maxLines: 3, validator: _required,
          decoration: InputDecoration(labelText: widget.leave ? 'Reason for leave' : 'Purpose / delivery details')),
        const SizedBox(height: 20),
        PrimaryButton(label: 'Save demo request', icon: Icons.add, onPressed: _submit),
      ])),
      const SectionHeading('Requests this session'),
      if (requests.isEmpty) const SurfaceCard(child: Text('No demo requests yet.')),
      for (final request in requests) Padding(padding: const EdgeInsets.only(bottom: 12),
        child: SurfaceCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(request.title, style: Theme.of(context).textTheme.titleMedium),
          const SizedBox(height: 8), Text(request.detail),
          const SizedBox(height: 12), const Text('Demo only • Not submitted'),
        ]))),
    ]));
  }
}

