class EmployeeShell extends StatefulWidget {
  const EmployeeShell({super.key, required this.session});
  final MockSessionController session;
  @override
  State<EmployeeShell> createState() => _EmployeeShellState();
}
class _EmployeeShellState extends State<EmployeeShell> {
  final _workday = WorkdayController();
  String _page = 'Home';
  static const _menu = [
    ('Home', Icons.home_outlined),
    ('Attendance', Icons.calendar_month_outlined),
    ('Leave Request', Icons.event_available_outlined),
    ('Material Request', Icons.add_box_outlined),
    ('Shift Roster', Icons.schedule),
    ('Tasks & Handover', Icons.checklist),
    ('Inventory', Icons.inventory_2_outlined),
    ('Barcode Scanner', Icons.qr_code_scanner),
    ('Stock Audit', Icons.fact_check_outlined),
    ('Store Operations', Icons.storefront_outlined),
    ('Announcements', Icons.campaign_outlined),
    ('Help & Support', Icons.help_outline),
    ('Profile', Icons.person_outline),
  ];
  void _open(String page) => setState(() => _page = page);
  @override
  void dispose() { _workday.dispose(); super.dispose(); }
  Widget _body() => switch (_page) {
    'Home' => HomeScreen(workday: _workday, onOpen: _open),
    'Attendance' => AttendanceScreen(workday: _workday, onLeave: () => _open('Leave Request')),
    'Leave Request' => RequestScreen(key: const ValueKey('leave-request'), workday: _workday, leave: true),
    'Material Request' => RequestScreen(key: const ValueKey('material-request'), workday: _workday, leave: false),
    'Profile' => ProfileScreen(session: widget.session),
    _ => ModuleScreen(title: _page),
  };
