  Widget build(BuildContext context) => PopScope(
    canPop: _page == 'Home',
    onPopInvokedWithResult: (didPop, result) { if (!didPop) _open('Home'); },
    child: Scaffold(
      appBar: AppBar(toolbarHeight: 80, title: const BrandLogo(width: 100),
        actions: [
          IconButton(tooltip: 'Open profile', onPressed: () => _open('Profile'),
            icon: const CircleAvatar(child: Text('AK'))),
          const SizedBox(width: 16),
        ]),
      drawer: Drawer(child: SafeArea(child: ListView(
        padding: const EdgeInsets.all(12), children: [
          const Center(child: BrandLogo(width: 150)),
          const Padding(padding: EdgeInsets.all(16),
            child: Text('FFC Employee Portal', style: TextStyle(fontWeight: FontWeight.w700))),
          for (final item in _menu) ListTile(
            selected: _page == item.$1, leading: Icon(item.$2),
            title: Text(item.$1),
            onTap: () { Navigator.pop(context); _open(item.$1); }),
          const Padding(padding: EdgeInsets.all(16),
            child: Text('UI demo • From Earth to Heart')),
        ]))),
      body: SafeArea(top: false, child: _body()),
      bottomNavigationBar: NavigationBar(
        selectedIndex: _page == 'Profile' ? 2 : (_page == 'Attendance' || _page == 'Leave Request') ? 1 : 0,
        onDestinationSelected: (index) => _open(['Home', 'Attendance', 'Profile'][index]),
        destinations: const [
          NavigationDestination(icon: Icon(Icons.home_outlined), label: 'Home'),
          NavigationDestination(icon: Icon(Icons.calendar_month_outlined), label: 'Attendance'),
          NavigationDestination(icon: Icon(Icons.person_outline), label: 'Profile'),
        ]),
    ));
}
